import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, AmbientLight, DirectionalLight } = ctx.THREE;

  const group = new Group();

  // 1. PALETTE & DESIGN TOKENS
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE BACKDROP (to prevent FLAT_VOID)
  // An elegant backing panel that grounds the features card
  const backGeo = new PlaneGeometry(3.4, 2.2);
  const backMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.85,
    metalness: 0.2,
    transparent: true,
    opacity: 0.95
  });
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.set(0, 0, -0.02);
  group.add(backMesh);

  // 3. ACCENT PRECISION SIGNAL LINE (Signal Red detail at bottom edge)
  const accentGeo = new PlaneGeometry(3.4, 0.03);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.2,
    roughness: 0.2,
    metalness: 0.8
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -1.1, -0.01);
  group.add(accentMesh);

  // 4. MAIN INTRO/FEATURE CARD
  const cardGeo = new PlaneGeometry(3.2, 2.0);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.5,
    metalness: 0.15,
    transparent: true,
    opacity: 1.0
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);

  // Load the card texture securely via the context
  const imageUrl = config.imageUrl ?? (config.intent?.visualSpec?.imageUrl);
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      cardMat.map = tex;
      // When textured, tone down paper high albedo to avoid BLOWN_WHITE_KEY
      cardMat.color.setHex(0xdddddd);
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load card texture, falling back to base color', err);
    });
  }

  // 5. LOCAL LIGHTING (Engineered Product Lighting)
  const localAmbient = new AmbientLight(colors.ink, 0.4);
  group.add(localAmbient);

  // Subtle directional key to catch bevels and define PBR paper/metalness
  const localKey = new DirectionalLight(colors.paper, 0.8);
  localKey.position.set(1.5, 2.0, 3.0);
  group.add(localKey);

  // Accent rim light casting signal red glow from the side
  const localRim = new DirectionalLight(colors.accent, 0.6);
  localRim.position.set(-2.0, -1.0, 1.0);
  group.add(localRim);

  // 6. ENTRANCE STAGE ANIMATION (Weighted Settle)
  group.position.y += 0.2;
  group.scale.set(0.95, 0.95, 0.95);

  const entranceTimeline = gsap.timeline();
  entranceTimeline.to(group.position, {
    y: 0,
    duration: 1.1,
    ease: 'power4.out'
  });
  entranceTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.3,
    ease: 'elastic.out(1, 0.75)'
  }, '-=1.1');

  // 7. CLEANUP
  group.userData = {
    cleanup() {
      if (entranceTimeline) entranceTimeline.kill();
      backGeo.dispose();
      backMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
    }
  };

  return group;
}
